  "legal.privacy.tahaAalamASoleProprietorTradingAsSophionosIsTheDesignate": "Ο Taha Aalam, ατομικός επιχειρηματίας που δραστηριοποιείται ως SophionOS, είναι ο καθορισμένος υπεύθυνος παραπόνων. Το γραμματοκιβώτιο παρακολουθείται και η ταχυδρομική διεύθυνση είναι δημοσιευμένη, ώστε να μπορεί να υποβληθεί παράπονο εγγράφως.",
