  "legal.privacy.n9GrievanceRedressal": "9. Επανόρθωση παραπόνων",
  "legal.privacy.weDoNotKnowinglyServeAdvertisingToChildrenAndWeDoNotUseB": "Δεν διαφημίζουμε συνειδητά σε παιδιά και δεν χρησιμοποιούμε καθόλου συμπεριφορική διαφήμιση.",
  "legal.privacy.ifYouBelieveAChildUnder18HasCreatedAnAccountOrProvidedPe": "Αν πιστεύετε ότι ένα παιδί κάτω των 18 έχει δημιουργήσει λογαριασμό ή παράσχει προσωπικά δεδομένα, επικοινωνήστε με τον υπεύθυνο παραπόνων. Θα διαγράψουμε τα δεδομένα αυτά μετά από επαλήθευση και δεν θα τα διατηρήσουμε κατά τη διερεύνηση του ζητήματος, πέραν όσων απαιτούνται για την επαλήθευση της αναφοράς.",
  "legal.privacy.theServiceIsForPeople18AndOverSoWeDoNotAskForAnAgeDeclar": "Η Υπηρεσία απευθύνεται σε άτομα ηλικίας 18 ετών και άνω, επομένως δεν ζητάμε δήλωση ηλικίας ούτε την καταγράφουμε. Δεν ζητάμε επαληθεύσιμη γονική συγκατάθεση, επειδή δεν επεξεργαζόμαστε προσωπικά δεδομένα παιδιών· αν μάθουμε ότι το κάναμε, θα τα διαγράψουμε.",
  "legal.privacy.theServiceIsNotDirectedAtChildrenAndIsNotIntendedForAnyo": "Η υπηρεσία δεν απευθύνεται σε παιδιά και δεν προορίζεται για κανέναν κάτω των 18. Δεν συλλέγουμε συνειδητά προσωπικά δεδομένα από παιδιά κάτω των 18.",
  "legal.privacy.n8ChildrenAndUnder18Users": "8. Παιδιά και χρήστες κάτω των 18",
  "legal.privacy.withdrawingConsentToMarketingStopsEveryPromotionalEmailI": "Η ανάκληση της συγκατάθεσης για εμπορική προώθηση διακόπτει κάθε διαφημιστικό email αμέσως, χωρίς άλλη επίδραση. Η ανάκληση της συγκατάθεσης για τους Όρους ή την Privacy Policy σημαίνει ότι η υπηρεσία δεν μπορεί πλέον να λειτουργήσει νόμιμα για εσάς, οπότε κλείνει ο λογαριασμός σας. Η εφαρμογή σας το αναφέρει πριν επιβεβαιώσετε και σας ζητά να πληκτρολογήσετε για επιβεβαίωση.",
  "legal.privacy.asPerTheBoardsProcess": "Σύμφωνα με τη διαδικασία του Board",
  "legal.privacy.youMayComplainToTheDataProtectionBoardAtAnyTimeInAdditio": "Μπορείτε να υποβάλετε παράπονο στο Data Protection Board ανά πάσα στιγμή, επιπλέον ή αντί της επικοινωνίας μαζί μας",
