  "legal.privacy.youHaveTheFollowingRightsEachOneHasAnInappControlNotJust": "Έχετε τα ακόλουθα δικαιώματα. Το καθένα έχει έλεγχο εντός της εφαρμογής, όχι απλώς μια παράγραφο πολιτικής, και το καθένα μπορεί να ασκηθεί χωρίς να στείλετε email σε κανέναν.",
  "legal.privacy.n7YourRights": "7. Τα δικαιώματά σας",
  "legal.privacy.weKeepBillingTaxAndAccountingRecordsForAsLongAsTheLawReq": "Διατηρούμε αρχεία χρέωσης, φορολογίας και λογιστικής για όσο χρόνο απαιτεί ο νόμος. Διατηρούμε αρχεία ασφάλειας και πρόσβασης για τουλάχιστον ένα έτος. Η Ινδία απαιτεί τουλάχιστον ένα έτος για τους Data Fiduciaries που επεξεργάζονται βάσει των DPDP Rules, 2025, και το ίδιο διάστημα καλύπτει τις ανάγκες μας για διερεύνηση συμβάντων παντού.",
  "legal.privacy.twoThingsFollowFromTheBackupWindowStatedPlainlyRatherTha": "Δύο πράγματα προκύπτουν από το παράθυρο των αντιγράφων ασφαλείας, διατυπωμένα καθαρά και όχι κρυμμένα: αν διαγράψετε τον λογαριασμό σας, ένα στιγμιότυπο που λήφθηκε έως και 30 days νωρίτερα ενδέχεται να περιέχει ακόμη τα δεδομένα σας μέχρι να απομακρυνθεί το στιγμιότυπο από την εναλλαγή· και δεν διατηρούμε αρχείο συγκατάθεσης, επειδή η χρήση της Υπηρεσίας αποτελεί την αποδοχή και η ισχύουσα έκδοση του παρόντος εγγράφου είναι αυτό με το οποίο συμφωνήσατε.",
  "legal.privacy.noneIsKeptAcceptanceIsTheUseOfTheServiceItselfSection2So": "Δεν διατηρείται κανένα. Η αποδοχή είναι η ίδια η χρήση της Υπηρεσίας (ενότητα 2), οπότε δεν υπάρχει κάτι ξεχωριστό να διατηρηθεί",
