  "legal.privacy.weDoNotUseAdvertisingCookiesCrosssiteTrackingCookiesOrFi": "Δεν χρησιμοποιούμε διαφημιστικά cookies, cookies διασταυριακής παρακολούθησης ή δακτυλοσκόπηση.",
  "legal.privacy.weUseASessionCookieToKeepYouSignedInWeUseLocalStorageFor": "Χρησιμοποιούμε ένα cookie συνεδρίας για να σας κρατήσουμε συνδεδεμένους. Χρησιμοποιούμε τοπικό αποθηκευτικό χώρο για προτιμήσεις διεπαφής και ένα αναγνωριστικό πρώτου μέρους, ώστε ένας αποσυνδεδεμένος επισκέπτης να μπορεί να συνδεθεί με τον λογαριασμό του κατά την εγγραφή.",
  "legal.privacy.n5CookiesAndLocalStorage": "5. Cookies και τοπικός αποθηκευτικός χώρος",
  "legal.privacy.weAreTheDataFiduciaryForTheDataYouCreateInTheServiceSect": ". Είμαστε ο Data Fiduciary για τα δεδομένα που δημιουργείτε στην Υπηρεσία (ενότητα 14) και για τα δεδομένα του λογαριασμού σας· ό,τι επιστρέφει σε εμάς είναι μόνο όσα χρειαζόμαστε για να χορηγήσουμε το δικαίωμα: το όνομα και το email σας, τα αναγνωριστικά πληρωμής και συνδρομής, και το γεγονός ότι η πληρωμή ολοκληρώθηκε.",
  "legal.privacy.dodopaymentscomprivacypolicy": "dodopayments.com/privacy-policy",
  "legal.privacy.forThatPaymentDataDodoPaymentsActsOnItsOwnAccountItDecid": "Για αυτά τα δεδομένα πληρωμής, η Dodo Payments ενεργεί για ίδιο λογαριασμό: αποφασίζει για ποιους λόγους και πώς επεξεργάζονται τα δεδομένα, για να σας πουλήσει και να εκπληρώσει τις δικές της νομικές, φορολογικές και προληπτικές απάτης υποχρεώσεις. Η δική της πολιτική απορρήτου της Dodo Payments ισχύει για τα δεδομένα αυτά και διέπει τα δικαιώματά σας επ' αυτών:",
  "legal.privacy.whosePrivacyPolicyApplies": "Ποια πολιτική απορρήτου ισχύει.",
  "legal.privacy.whichGoToDodoPaymentsAndItsPaymentServiceProvidersAndNev": ", τα οποία πηγαίνουν στη Dodo Payments και στους παρόχους υπηρεσιών πληρωμής της και δεν φτάνουν ποτέ σε εμάς. Δεν τα βλέπουμε ούτε τα αποθηκεύουμε ποτέ.",
