  "legal.privacy.dodoPaymentsIsTheSellerOfRecordForThatPurchaseItTakesYou": ". Η Dodo Payments είναι ο πωλητής εγγραφής για την αγορά αυτή: λαμβάνει την πληρωμή σας, εκδίδει το τιμολόγιο, επιβάλλει και αποδίδει τους εφαρμοστέους φόρους και εκδίδει τυχόν επιστροφή χρημάτων στην κάρτα με την οποία πληρώσατε. Η σύμβαση αγοράς συνάπτεται μεταξύ εσάς και της Dodo Payments, βάσει των δικών της όρων πώλησης. Η χρήση της Υπηρεσίας διέπεται από τους",
