  "legal.privacy.weDoNotSendYourContentNotesContactsOrPromptsToAnyThirdpa": "Δεν αποστέλλουμε το περιεχόμενο, τις σημειώσεις, τις επαφές ή τα ερωτήματά σας σε κανέναν πάροχο αναλυτικών στοιχείων τρίτου μέρους. Συλλέγουμε μόνο συγκεντρωτικά, μη σχετικά με περιεχόμενο, λειτουργικά μετρητικά στοιχεία για την απόδοση της υπηρεσίας.",
