  "legal.privacy.ifAClientIsEverExtendedToANewDataTypeOrANewUseForExample": "Αν ένας πελάτης επεκταθεί ποτέ σε νέο τύπο δεδομένων ή νέα χρήση, π.χ. στην ανάγνωση περιεχομένου που δεν έχετε ανοίξει, αυτό αποτελεί νέο σκοπό. Δεν προστίθεται σιωπηρά στον κατάλογο αυτό: απαιτεί νέα έκδοση της παρούσας Πολιτικής, που δημοσιεύεται πριν από οποιαδήποτε νέα συλλογή. Δείτε Ρυθμίσεις → Πρόσβαση AI για να ελέγξετε και να ανακαλέσετε την πρόσβαση AI ανά πάσα στιγμή.",
  "legal.privacy.ifYouCreateAnApiKeyAndConnectClaudeCursorCodexOrAnotherM": "Αν δημιουργήσετε κλειδί API και συνδέσετε τα Claude, Cursor, Codex ή άλλον πελάτη MCP, ο πελάτης αυτός καλεί το SophionOS και ο πάροχός του επεξεργάζεται όσα λαμβάνει. Αυτό συμβαίνει μόνο επειδή το ρυθμίσατε εσείς και είναι εκτός του ελέγχου μας μετά την αποστολή του αιτήματος. Δείτε",
