  "legal.terms.billingSurfacesAppearInSettingsBillingOnlyWhenBillingIsE": "Οι οθόνες χρέωσης εμφανίζονται στις Ρυθμίσεις → Χρέωση μόνο όταν η χρέωση είναι ενεργοποιημένη για την εγκατάστασή σας.",
  "legal.terms.mcpAndApiRoutesThatRequireAPaidPlanReturn403ForFreeKeys": "Οι διαδρομές MCP και API που απαιτούν επί πληρωμή πρόγραμμα επιστρέφουν 403 για κλειδιά Free.",
  "legal.terms.theAuthoritativeNumbersArePublishedInTheAppUnderSettings": "Οι επίσημοι αριθμοί δημοσιεύονται στην εφαρμογή στις Ρυθμίσεις → Πρόσβαση AI. Η υπέρβαση ορίου επιστρέφει HTTP 429· μειώστε τον ρυθμό και δοκιμάστε ξανά.",
  "legal.terms.rateLimitsArePerMinuteAndEnforcedPerPlan": "Τα όρια ρυθμού είναι ανά λεπτό και επιβάλλονται ανά πρόγραμμα.",
  "legal.terms.governedCompanyContextAndCompanyBrainOrganizationWorkspa": "Κυβερνημένο πλαίσιο εταιρείας και Company Brain: χώροι εργασίας και ρόλοι οργανισμού, πολιτικές πρόσβασης AI και αρχεία ελέγχου, αναζήτηση με επίγνωση δικαιωμάτων, SSO και SCIM, SLA και υποστήριξη υλοποίησης, και επιλογές διαμονής δεδομένων. Διέπεται από υπογεγραμμένη παραγγελία ή συμφωνία, όπου υπάρχει.",
