  "legal.terms.theManagedPersonalWorkspaceWithA100entityCapAreasGoalsPr": "Ο διαχειριζόμενος προσωπικός χώρος εργασίας με όριο 100 οντοτήτων (περιοχές, στόχοι, έργα, εργασίες, σημειώσεις, πόροι, επαφές, αρχεία επαφών μαζί), διατήρηση δραστηριότητας 7-day και χρήση μέσω της διαδικτυακής εφαρμογής. Η πρόσβαση REST API και MCP δεν περιλαμβάνεται και απαιτεί επί πληρωμή πρόγραμμα.",
