  "legal.terms.theServiceIsOfferedOnThePlansBelowPricesAreInUsDollarsAn": "Η Υπηρεσία προσφέρεται στα παρακάτω προγράμματα. Οι τιμές είναι σε δολάρια ΗΠΑ και μπορεί να αλλάξουν· μια αλλαγή δεν ισχύει ποτέ αναδρομικά σε περίοδο που έχετε ήδη πληρώσει. Τα όρια επιβάλλονται τεχνικά, όχι απλώς περιγράφονται: ένας λογαριασμός που υπερβαίνει όριο ή όριο ρυθμού λαμβάνει σφάλμα, όχι επιπλέον χρέωση.",
  "legal.terms.n3PlansTiersAndTechnicalLimits": "3. Προγράμματα, επίπεδα και τεχνικά όρια",
  "legal.terms.weMaySuspendOrTerminateAnAccountThatBreachesTheseTermsTh": "Μπορούμε να αναστείλουμε ή να λύσουμε λογαριασμό που παραβιάζει τους παρόντες Όρους, που υποχρεούμαστε να αναστείλουμε από τον νόμο ή που εύλογα πιστεύουμε ότι χρησιμοποιείται για πρόκληση ζημίας. Όπου το επιτρέπει ο νόμος, θα σας πούμε τον λόγο και θα σας δώσουμε την ευκαιρία να διορθώσετε το πρόβλημα πρώτα.",
  "legal.terms.keepOnePersonToOneAccountAndDoNotShareAnAccountBetweenMu": "Διατηρείτε ένα πρόσωπο ανά λογαριασμό και μην μοιράζεστε λογαριασμό μεταξύ πολλών ατόμων. Είστε υπεύθυνοι για τη δραστηριότητα στις συνεδρίες και τα κλειδιά API σας μέχρι να τα ανακαλέσετε ή να αποσυνδεθείτε.",
  "legal.terms.allActivityThatHappensUnderYourAccountIncludingActivityB": "όλη η δραστηριότητα που πραγματοποιείται στον λογαριασμό σας, συμπεριλαμβανομένης της δραστηριότητας οποιουδήποτε στο οποίο δίνετε πρόσβαση.",
  "legal.terms.keepingYourCredentialsConfidentialAndNotifyingUsAtOnceIf": "να διατηρείτε τα διαπιστευτήριά σας εμπιστευτικά και να μας ενημερώσετε αμέσως αν πιστεύετε ότι ο λογαριασμός έχει παραβιαστεί·",
