  "legal.terms.weMayModifySuspendOrDiscontinueFeaturesWhereAChangeMater": "Μπορούμε να τροποποιήσουμε, να αναστείλουμε ή να διακόψουμε λειτουργίες. Όπου μια αλλαγή μειώνει ουσιαστικά λειτουργικότητα στην οποία βασίζεστε, θα σας ενημερώσουμε εύλογα εκ των προτέρων στην εφαρμογή πριν τεθεί σε ισχύ.",
