  "legal.terms.theServiceIsUnderActiveDevelopmentExpectRoughEdgesSchema": "Η Υπηρεσία βρίσκεται υπό ενεργό ανάπτυξη. Αναμένετε τραχιές άκρες, αλλαγές σχήματος και ατελή εργαλεία φορέα εκμετάλλευσης. Το REST API (",
  "legal.terms.weDoNotWarrantThatTheServiceWillBeUninterruptedErrorfree": ". Δεν εγγυόμαστε ότι η Υπηρεσία θα είναι αδιάλειπτη, χωρίς σφάλματα ή κατάλληλη για συγκεκριμένο σκοπό, εκτός όπου ο νόμος ορίζει διαφορετικά.",
  "legal.terms.asIs": "ως έχει",
  "legal.terms.sophionosIsProvided": "Το SophionOS παρέχεται",
  "legal.terms.dodoPaymentsTakesYourPaymentIssuesTheInvoiceAppliesAndRe": ": η Dodo Payments λαμβάνει την πληρωμή σας, εκδίδει το τιμολόγιο, επιβάλλει και αποδίδει τους εφαρμοστέους φόρους και εκδίδει επιστροφές, και η αγορά σας αποτελεί σύμβαση με τη Dodo Payments βάσει των όρων πώλησής της. Όσα αφορούν χρέωση, τιμολόγιο, φόρο, επιστροφή χρημάτων ή ακύρωση αγοράς ανήκουν στη Dodo Payments ως αντισυμβαλλόμενη και όχι σε εμάς. Οι ενότητες 4 και 11 καλύπτουν τα μέρη αυτών που διαχειρίζεστε μέσω μας, συμπεριλαμβανομένου σφάλματος χρέωσης ή διπλής χρέωσης.",
  "legal.terms.theseTermsGovernYourUseOfTheServiceTheyAreNotTheContract": "Οι παρόντες Όροι διέπουν τη χρήση σας της Υπηρεσίας. Δεν αποτελούν τη σύμβαση για την ίδια την αγορά. Τα επί πληρωμή προγράμματα και οι θέσεις Founding Cohort πωλούνται από τη \"Dodo Payments\" (όπως ορίζεται στη Master Service Agreement της Dodo Payments: Dodo Payments Inc., Dodope Payments Limited και Sarvapanchhi Technologies Private Limited, συλλογικά ο merchant of record) ως",
  "legal.terms.inTheseTermsSophionosWeUsMeansTahaAalamASoleProprietorTr": "Στους παρόντες Όρους, τα \"SophionOS\", \"we\", \"us\" σημαίνουν τον Taha Aalam, ατομικό επιχειρηματία που δραστηριοποιείται ως SophionOS, ο οποίος διαχειρίζεται την υπηρεσία SophionOS Cloud, και το \"you\" σημαίνει το πρόσωπο που τη χρησιμοποιεί. Ο όρος \"Service\" σημαίνει την υπηρεσία SophionOS Cloud και το λογισμικό SophionOS Core που διανέμουμε για αυτοφιλοξενία.",
  "legal.terms.sophionosIsALifeOperatingSystemAndSystemOfRecordForInter": "Το SophionOS είναι ένα λειτουργικό σύστημα ζωής και σύστημα καταγραφής για διασυνδεδεμένους τομείς της ζωής: περιοχές, στόχοι, έργα, εργασίες, σημειώσεις, πόροι, θέματα και επαφές, μαζί με τις σχέσεις μεταξύ τους. Ο πίνακας ελέγχου είναι η επιφάνεια εντολών· οι ρυθμίσεις, η εξαγωγή, η διαγραφή, τα κλειδιά API και ο διακομιστής MCP σας επιτρέπουν να ελέγχετε και να συνδέετε αυτό το περιεχόμενο.",
  "legal.terms.n1TheService": "1. Η υπηρεσία",
  "legal.terms.andOurMarketingCommunicationsPolicyEachIsConsentedToInde": "και την πολιτική μας Εμπορικής προώθησης & Επικοινωνίας. Η καθεμία αποτελεί αντικείμενο ξεχωριστής συγκατάθεσης.",
  "legal.terms.theseTermsGovernYourAccessToAndUseOfTheSophionosPlatform": "Οι παρόντες Όροι διέπουν την πρόσβασή σας και τη χρήση της πλατφόρμας SophionOS, συμπεριλαμβανομένης της φιλοξενούμενης υπηρεσίας SophionOS Cloud και κάθε αυτοφιλοξενούμενης εγκατάστασης που διανέμουμε (η \"Service\"). Αποτελούν ξεχωριστό έγγραφο από τους",
  "legal.terms.termsConditionsOfUse": "Όροι και Προϋποθέσεις Χρήσης",
  "legal.terms.thisDocumentIsProductTextAwaitingReviewByQualifiedIndian": "Το παρόν έγγραφο είναι κείμενο προϊόντος που αναμένει έλεγχο από ειδικευμένους Ινδούς νομικούς συμβούλους. Δεν πρέπει να δημοσιευθεί ως δεσμευτικό μέχρι οι σύμβουλοι να το εγκρίνουν. Κάθε ρήτρα υπόκειται στον έλεγχο αυτό.",
  "legal.terms.adoptsTheReviewedAndCorrectedSophionosTermsConditionsV2E": "Υιοθετεί τους ελεγμένους και διορθωμένους Όρους και Προϋποθέσεις v2 του SophionOS, effective 19 October 2026· το κείμενο εξακολουθεί να είναι DRAFT εν αναμονή έγκρισης από ειδικευμένους Ινδούς νομικούς συμβούλους.",
  "legal.terms.theTermsThatGovernUseOfTheSophionosPlatformTheServiceAcc": "Οι όροι που διέπουν τη χρήση της πλατφόρμας SophionOS: η υπηρεσία, οι λογαριασμοί, τα προγράμματα και τα όρια, οι θέσεις ιδρυτών, η επιτρεπτή χρήση, η πρόσβαση API και MCP, το περιεχόμενό σας, η χρέωση, οι διαφορές και το εφαρμοστέο δίκαιο.",
  "legal.security.thisPageIsProductDocumentationNotLegalCounsel": "Η παρούσα σελίδα αποτελεί τεκμηρίωση προϊόντος, όχι νομική συμβουλή.",
