  "legal.security.reportVulnerabilitiesThrough": "Αναφέρετε ευπάθειες μέσω",
  "legal.security.aFormalThirdpartySecurityAuditOrACertificationSuchAsSoc2": "Ένας επίσημος έλεγχος ασφαλείας τρίτου μέρους ή πιστοποίηση όπως SOC 2 ή ISO 27001. Δεν διαθέτουμε κανένα σήμερα και δεν θα αυτοαποκαλούμαστε ελεγμένοι μέχρι να υπάρξει κάτι τέτοιο.",
  "legal.security.endtoendEncryptionWeDoNotOfferItAndWeWillNotDescribeTheS": "Κρυπτογράφηση από άκρο σε άκρο. Δεν την προσφέρουμε και δεν θα περιγράψουμε την υπηρεσία ως κρυπτογραφημένη από άκρο σε άκρο. Η κρυπτογράφηση πεδίων προστατεύει το περιεχόμενό σας κατά την αποθήκευση στη βάση μας, αλλά ο διακομιστής έχει το κλειδί, οπότε η αναζήτηση, οι πίνακες ελέγχου και οι ενημερώσεις με email που ενεργοποιείτε μπορούν να διαβάσουν το περιεχόμενό σας.",
  "legal.security.thatExternalAiProvidersNeverReceiveDataAfterYouConnectAC": "Ότι οι εξωτερικοί πάροχοι AI δεν λαμβάνουν ποτέ δεδομένα μετά τη σύνδεση πελάτη· τα λαμβάνουν, επειδή αυτό κάνει ακριβώς η σύνδεση ενός πελάτη.",
  "legal.security.militarygradeSecurityOrZeroRisk": "Ασφάλεια στρατιωτικού επιπέδου ή μηδενικός κίνδυνος.",
  "legal.security.thatWeCannotReadYourDataSophionosCloudHoldsTheEncryption": "Ότι δεν μπορούμε να διαβάσουμε τα δεδομένα σας: το SophionOS Cloud διατηρεί το κλειδί κρυπτογράφησης στον διακομιστή, οπότε ο ρόλος υπηρεσίας μας και ο φορέας εκμετάλλευσης μπορούν να διαβάσουν το περιεχόμενό σας. Δεν εφαρμόζουμε αρχιτεκτονική zero-knowledge.",
  "legal.security.whatWeDoNotClaim": "Τι δεν ισχυριζόμαστε",
  "legal.security.understandThatOnceYouConnectAnAiClientThatClientAndItsPr": "Κατανοήστε ότι μόλις συνδέσετε έναν πελάτη AI, ο πελάτης αυτός και ο πάροχός του επεξεργάζονται όσα λαμβάνουν βάσει των δικών τους όρων.",
  "legal.security.treatAnApiKeyAsYourFullIdentityOnTheApiSurfaceItReachesG": "Αντιμετωπίστε ένα κλειδί API ως την πλήρη ταυτότητά σας στην επιφάνεια API που καλύπτει. Δώστε στα κλειδιά σύντομη λήξη, χρησιμοποιήστε μόνο ανάγνωση όπου είναι δυνατόν και ανακαλέστε τα κλειδιά που δεν χρησιμοποιείτε πλέον.",
  "legal.security.useAUniquePasswordOnTheIdentityProviderAndTurnOnMultifac": "Χρησιμοποιήστε μοναδικό κωδικό πρόσβασης στον πάροχο ταυτότητας και ενεργοποιήστε εκεί την πολυπαραγοντική ταυτοποίηση.",
  "legal.security.yourPart": "Το δικό σας μέρος",
