  "legal.security.rule6Requirement": "Απαίτηση Rule 6",
  "legal.security.whereTheDpdpRules2025ApplyRule6RequiresADataFiduciaryToT": "Όπου εφαρμόζονται οι DPDP Rules, 2025, ο Rule 6 απαιτεί από έναν Data Fiduciary να λάβει, κατ' ελάχιστον, τα ακόλουθα μέτρα. Όπου εφαρμόζονται σε εσάς, τα πληρούμε ως εξής:",
  "legal.security.indiaMinimumSafeguardsUnderRule6DpdpRules2025": "Ινδία: ελάχιστα μέτρα ασφαλείας βάσει του Rule 6, DPDP Rules 2025",
  "legal.security.productionCredentialsAreHeldByTheFounderoperatorAndUsedF": ": τα διαπιστευτήρια παραγωγής διατηρεί ο ιδρυτής/φορέας εκμετάλλευσης και χρησιμοποιούνται για απόκριση σε συμβάν, κλιμάκωση υποστήριξης που ξεκινάτε εσείς ή νομική διαδικασία. Η υποστήριξη δεν θα ζητήσει ποτέ μυστικά κλειδιά API, κωδικούς πρόσβασης, διακριτικά συνεδρίας ή πλήρη εξαγωγή των σημειώσεών σας.",
  "legal.security.operatorAccess": "Πρόσβαση φορέα εκμετάλλευσης",
  "legal.security.cloudTakesProviderbackedBackupsTheyAreNotZeroknowledgeTh": ": το Cloud λαμβάνει αντίγραφα ασφαλείας με εγγύηση παρόχου. Δεν είναι zero-knowledge: ο φορέας εκμετάλλευσης έχει το κλειδί κρυπτογράφησης, οπότε το περιεχόμενο ενός αντιγράφου είναι αναγνώσιμο από εμάς.",
