  "legal.security.loggingAndVisibility": "Καταγραφή και ορατότητα",
  "legal.security.aGlobalAiaccessSwitchASeparateWriteaccessSwitchPerkeyWri": ": ένας καθολικός διακόπτης πρόσβασης AI, ένας ξεχωριστός διακόπτης πρόσβασης εγγραφής, λειτουργίες εγγραφής ανά κλειδί και μεταδεδομένα δραστηριότητας που μπορείτε να ελέγξετε. Η ανάκληση κλειδιού απορρίπτει τις επόμενες αιτήσεις αμέσως.",
  "legal.security.aiControls": "Έλεγχοι AI",
  "legal.security.storedOnlyAsCryptographicHashesShownOnceAtCreationRevoca": ": αποθηκεύονται μόνο ως κρυπτογραφικά hashes, εμφανίζονται μία φορά κατά τη δημιουργία, ανακαλούνται, με προαιρετική λήξη, ετικέτες και πεδία ανά κλειδί, και με προεπιλεγμένη στάση μόνο ανάγνωσης για το MCP.",
  "legal.security.providersideEncryptionOnTheirStorageLayerPlusApplication": ": κρυπτογράφηση από τον πάροχο στο επίπεδο αποθήκευσής του, συν κρυπτογράφηση πεδίων σε επίπεδο εφαρμογής του προσωπικού σας περιεχομένου. Στο SophionOS Cloud, τα σώματα των σημειώσεων, τα στοιχεία επαφών και οι περιγραφές και οι αποθηκευμένοι σύνδεσμοι στις περιοχές, στόχους, έργα, εργασίες και πόρους σας κρυπτογραφούνται με AES-256-GCM πριν γραφούν στη βάση δεδομένων. Αυτό ισχύει πάντα για κάθε λογαριασμό Cloud και το κλειδί δεν φτάνει ποτέ στον φυλλομετρητή. Δεν αποτελεί κρυπτογράφηση από άκρο σε άκρο· ο διακομιστής έχει το κλειδί.",
  "legal.security.encryptionAtRest": "Κρυπτογράφηση κατά την αποθήκευση",
  "legal.security.allTrafficIsServedOverTlsAndAPerrequestNoncebasedContent": ": όλη η κίνηση εξυπηρετείται μέσω TLS και μια πολιτική Content Security Policy βάσει μη επαναχρησιμοποιούμενου αριθμού ανά αίτημα περιορίζει ποια σενάρια θα εκτελέσει η εφαρμογή.",
  "legal.security.encryptionInTransit": "Κρυπτογράφηση κατά τη μεταφορά",
  "legal.security.free": "δωρεάν",
  "legal.security.postgresRowlevelSecurityEnforcesThatASessionSeesOnlyItsO": ": η ασφάλεια γραμμών της Postgres επιβάλλει ότι μια συνεδρία βλέπει μόνο τις γραμμές του δικού της χρήστη. Η διαδρομή κλειδιού API φιλτράρει κάθε ερώτημα με βάση το αναγνωριστικό του επαληθευμένου χρήστη. Οι έλεγχοι προγράμματος και δικαιώματος γίνονται στον διακομιστή και λειτουργούν fail-closed: μια απουσιάζουσα ή ανενεργή συνδρομή επιλύεται σε",
  "legal.security.peruserIsolation": "Απομόνωση ανά χρήστη",
