  "legal.security.howSophionosProtectsYourData": "Πώς προστατεύει το SophionOS τα δεδομένα σας.",
  "legal.subprocessors.weAddAVendorOnlyWhenAFeatureNeedsItAndWeUpdateThisPageAt": "Προσθέτουμε πάροχο μόνο όταν κάποια λειτουργία το απαιτεί, και ενημερώνουμε τη σελίδα αυτή ταυτόχρονα. Αν μια αλλαγή επηρεάζει ουσιαστικά τον τρόπο επεξεργασίας των προσωπικών σας δεδομένων, σας ενημερώνουμε με email πριν τεθεί σε ισχύ και μπορείτε να αντιταχθείτε ή να διαγράψετε πρώτα τον λογαριασμό σας. Για να ενημερώνεστε για αλλαγές ή να υποβάλετε ένσταση, γράψτε στο",
