  "legal.subprocessors.dodoPaymentsIsTheExceptionItIsOurMerchantOfRecordAndTheS": "Η Dodo Payments αποτελεί την εξαίρεση. Είναι ο merchant of record και ο πωλητής εγγραφής μας για τα επί πληρωμή προγράμματα και τις θέσεις ιδρυτών, οπότε αποφασίζει πώς επεξεργάζονται τα δεδομένα πληρωμής σας αντί να τα επεξεργάζεται βάσει των εντολών μας, και η δική της",
  "legal.subprocessors.underIndiasDpdpAct2023TahaAalamSoleProprietorTradingAsSo": "Βάσει του DPDP Act, 2023 της Ινδίας, ο Taha Aalam, ατομικός επιχειρηματίας που δραστηριοποιείται ως SophionOS, είναι ο Data Fiduciary και αυτοί οι πάροχοι είναι οι Data Processors μας· όπου εφαρμόζεται ο GDPR της ΕΕ ή του ΗΒ, εμείς είμαστε ο ελεγκτής και εκείνοι οι επεξεργαστές μας. Ο καθένας δεσμεύεται συμβατικά να επεξεργάζεται προσωπικά δεδομένα μόνο βάσει των εντολών μας και να εφαρμόζει μέτρα ασφαλείας. Η σελίδα αυτή παραθέτει ποιοι είναι και γιατί.",
  "legal.subprocessors.replacesThePreviousVendorListNamesTheActualVendorsNowInU": "Αντικαθιστά τον προηγούμενο κατάλογο παρόχων. Κατονομάζει τους πραγματικούς παρόχους που χρησιμοποιούνται πλέον: τη Dodo Payments για τη χρέωση συνδρομής και την εφάπαξ ολοκλήρωση αγοράς founding-seat, και τη Resend για το συναλλακτικό email, και διαχωρίζει όσα χρησιμοποιεί η υπηρεσία Cloud από όσα χρησιμοποιεί μια αυτοφιλοξενούμενη εγκατάσταση.",
